const ScriptBlock *scriptForRoom(int room, uint &count) {
	for (uint i = 0; i < ARRAYSIZE(kRooms); i++) {
		if (kRooms[i].room == room) {
			count = kRooms[i].count;
			return &kBlocks[kRooms[i].first];
		}
	}

	count = 0;
	return nullptr;
}

const ScriptEffect *scriptEffect(uint index) {
	return &kEffects[index];
}

const ScriptFlagInit *initialFlags(uint &count) {
	count = ARRAYSIZE(kInitialFlags);
	return kInitialFlags;
}

